// Weekly insights: counts and an LLM-written summary, generated by the agent's
// backend into cafes/{id}/insights/{weekStart}. This screen only displays them.
import { ActivityIndicator, ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { Banner } from "@/components/Banner";
import { EmptyState } from "@/components/EmptyState";
import { Palette } from "@/constants/Colors";
import { Radius, Spacing, Typography } from "@/constants/Typography";
import { useInsights } from "@/hooks/useInsights";
import { countRows, weekLabel } from "@/lib/insights";
import { useCafe } from "@/lib/owner-context";

export default function InsightsScreen() {
  const cafe = useCafe();
  const { loading, weeks, error } = useInsights(cafe.id);

  return (
    <SafeAreaView style={styles.root} edges={["top"]}>
      <ScrollView contentContainerStyle={styles.content}>
        <Text style={styles.title} accessibilityRole="header">
          Insights
        </Text>
        <Text style={styles.subtitle}>
          What customers asked JOLO about {cafe.name}, week by week.
        </Text>

        {error ? <Banner kind="error">Couldn't load insights.</Banner> : null}
        {loading ? <ActivityIndicator color={Palette.primary} /> : null}
        {!loading && weeks.length === 0 ? (
          <EmptyState icon="stats-chart-outline" title="No insights yet">
            Insights are written once a week, after customers start asking about your menu.
          </EmptyState>
        ) : null}

        {weeks.map((week, index) => (
          <View key={week.weekStart} style={[styles.card, index === 0 && styles.cardLatest]}>
            <Text style={styles.week}>
              {weekLabel(week.weekStart)}
              {index === 0 ? " · latest" : ""}
            </Text>

            <View style={styles.counts}>
              {countRows(week.counts).map((row) => (
                <View
                  key={row.key}
                  style={styles.count}
                  accessible
                  accessibilityLabel={`${row.label}: ${row.value}`}
                >
                  <Text style={styles.countValue}>{row.value}</Text>
                  <Text style={styles.countLabel}>{row.label}</Text>
                </View>
              ))}
            </View>

            {week.topItems.length > 0 ? (
              <View style={styles.block}>
                <Text style={styles.blockTitle}>Most asked about</Text>
                {week.topItems.slice(0, 5).map((item) => (
                  <Text key={item.name} style={styles.topItem}>
                    {item.name} · {item.mentions} {item.mentions === 1 ? "mention" : "mentions"}
                  </Text>
                ))}
              </View>
            ) : null}

            {week.summary ? (
              <View style={styles.block}>
                <Text style={styles.blockTitle}>Summary</Text>
                <Text style={styles.summary}>{week.summary}</Text>
              </View>
            ) : null}
          </View>
        ))}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: Palette.background },
  content: { padding: Spacing.marginMain, gap: Spacing.stackSm },
  title: { ...Typography.headlineLgMobile, color: Palette.primary },
  subtitle: { ...Typography.bodySm, color: Palette.onSurfaceVariant, marginBottom: Spacing.xs },
  card: {
    backgroundColor: Palette.surfaceContainerLow,
    borderRadius: Radius.lg,
    padding: Spacing.cardPadding,
    gap: Spacing.sm,
  },
  cardLatest: { borderWidth: 2, borderColor: Palette.secondaryContainer },
  week: { ...Typography.labelLg, color: Palette.secondary },
  counts: { flexDirection: "row", flexWrap: "wrap", gap: Spacing.sm },
  count: {
    minWidth: 96,
    flexGrow: 1,
    backgroundColor: Palette.surfaceContainerLowest,
    borderRadius: Radius.md,
    padding: Spacing.xs + 4,
  },
  countValue: { ...Typography.headlineMd, color: Palette.primary, fontVariant: ["tabular-nums"] },
  countLabel: { ...Typography.labelMd, color: Palette.onSurfaceVariant },
  block: { gap: 4 },
  blockTitle: { ...Typography.labelLg, color: Palette.onSurface },
  topItem: { ...Typography.bodySm, color: Palette.onSurface },
  summary: { ...Typography.bodyMd, color: Palette.onSurface },
});
